---------- VAMain.lua ----------

local DESIGN_SIZE = 1080
local RENDER_RATIO = 2.0
local DURATION = 23 / 30

local function tr (x)
    return ((RENDER_RATIO - 1) * 0.5 + x) / RENDER_RATIO
end

local VAMain = {}
VAMain.__index = VAMain
function VAMain.new ()
    return setmetatable({}, VAMain)
end


function VAMain:create (node, data, w, h, scene)
    Helper.initPipeline(scene, "@Pipeline")

    node.motion = scene:findEntityBy("motion"):getComponent("MeshRenderer").material
    node.motion:setFloat("u_ratio", RENDER_RATIO)

    node.bx1 = scene:findEntityBy("bx1"):getComponent("MeshRenderer").material
    node.bx2 = scene:findEntityBy("bx2"):getComponent("MeshRenderer").material
    node.bx3 = scene:findEntityBy("bx3"):getComponent("MeshRenderer").material
    node.bx4 = scene:findEntityBy("bx4"):getComponent("MeshRenderer").material
    node.by1 = scene:findEntityBy("by1"):getComponent("MeshRenderer").material

    node.wave = scene:findEntityBy("wave"):getComponent("MeshRenderer").material
    node.expo = scene:findEntityBy("expo"):getComponent("MeshRenderer").material
    node.crop = scene:findEntityBy("crop"):getComponent("MeshRenderer").material
    node.crop:setFloat("u_ratio", RENDER_RATIO)

    node.rt0 = scene:findEntityBy("camera_bx1"):getComponent("Camera").renderTexture
    node.rt1 = scene:findEntityBy("camera_bx2"):getComponent("Camera").renderTexture

    data.ae = AEAdapter:new()
    data.ae:addKeyframes("", AE)
end

function VAMain:layout (node, data, w, h)
    local ew = w * RENDER_RATIO
    local eh = h * RENDER_RATIO
    node.rt0.width = ew
    node.rt0.height = eh
    node.rt1.width = ew
    node.rt1.height = eh

    local s = math.min(w, h) / 720
    w = w / s
    h = h / s
    ew = ew / s
    eh = eh / s
    data.s = math.min(w, h)
    data.w = w
    data.h = h

    node.bx1:setFloat("u_step_x", 1 / ew)
    node.bx2:setFloat("u_step_x", 1 / ew)
    node.bx3:setFloat("u_step_x", 1 / ew)
    node.bx4:setFloat("u_step_x", 1 / ew)
    node.by1:setFloat("u_step_y", 1 / eh)

    node.motion:setVec2("u_screen_size", Amaz.Vector2f(ew, eh))
    node.wave:setVec2("u_screen_size", Amaz.Vector2f(ew, eh))
end

function VAMain:update (node, data, w, h, duration, elapsed, progress)
    elapsed = progress * DURATION

    local p = data.ae:get("/ADBE Position", elapsed)
    local x = p[1] / DESIGN_SIZE
    local y = 1 - p[2] / DESIGN_SIZE
    node.motion:setVec2("u_position", Amaz.Vector2f(tr(x), tr(y)))

    local s = data.ae:get("/ADBE Scale", elapsed)[1] * 0.01
    node.motion:setFloat("u_scale", s)

    local b = data.ae:get("/ADBE Gaussian Blur 2-0001", elapsed)[1] / DESIGN_SIZE
    node.by1:setFloat("u_radius", b * 3 * 0.4)
    b = b * data.s * 0.4
    node.bx1:setFloat("u_radius", b)
    node.bx2:setFloat("u_radius", b * 0.5)
    node.bx3:setFloat("u_radius", b * 0.25)
    node.bx4:setFloat("u_radius", b * 0.125)

    local a = data.ae:get("/ADBE Wave Warp-0002", elapsed)[1] / DESIGN_SIZE * data.w
    node.wave:setFloat("u_amplitude", a)
    local l = data.ae:get("/ADBE Wave Warp-0003", elapsed)[1] / DESIGN_SIZE * data.s * 2.1
    node.wave:setFloat("u_wavelength", l)

    local e = data.ae:get("/ADBE Exposure2-0003", elapsed)[1]
    node.expo:setFloat("u_exposure", e)
end







---------- VAEntry.lua ----------

local exports = exports or {}
local SeekModeScript = SeekModeScript or {}
SeekModeScript.__index = SeekModeScript


function SeekModeScript.new (construct, ...)
    local self = setmetatable({}, SeekModeScript)

    self.curTime = 0
    self.duration = 1

    self.node = {}
    self.data = {}
    self.main = VAMain.new()

    return self
end

function SeekModeScript:onStart (comp)
    self:_adapt_onStart(comp)
    self.rootDir = comp.entity.scene.assetMgr.rootDir
    --
    self.data.w0 = Amaz.BuiltinObject.getInputTextureWidth()
    self.data.h0 = Amaz.BuiltinObject.getInputTextureHeight()
    self.main:create(self.node, self.data, self.data.w0, self.data.h0, comp.entity.scene)
    self.main:layout(self.node, self.data, self.data.w0, self.data.h0)
    self.main:update(self.node, self.data, self.data.w0, self.data.h0, 1, 0, 0)
    --
end

function SeekModeScript:seek (time)
    self:_adapt_seek(time)
    --
    local w = Amaz.BuiltinObject.getInputTextureWidth()
    local h = Amaz.BuiltinObject.getInputTextureHeight()
    if w ~= self.data.w0 or h ~= self.data.h0 then
        self.data.w0 = w
        self.data.h0 = h
        self.main:layout(self.node, self.data, self.data.w0, self.data.h0)
    end
    self.main:update(self.node, self.data, self.data.w0, self.data.h0, self.duration, time, time / self.duration)
    --
end

function SeekModeScript:setParams (name, value)
    if name == "u_size" then
        -- local bgAspect = value.x / value.y
        -- local videoAspect = value.z / value.w
        -- if bgAspect > videoAspect then
        --     self.scaleCorrect = value.w / value.y
        -- else
        --     self.scaleCorrect = value.z / value.x
        -- end
        -- self.videoMat:setVec4("u_size", value)
        -- self.modelMat:setVec4("u_size", value)
        local FBS = Amaz.Vector2f(value.x, value.y)
        self.fxaaMat:setVec2("FBS", FBS)
        self.blendMat:setVec4("u_size", value)
    elseif name == "u_pos" then
        -- self.videoMat:setVec2("u_pos", value)
        -- self.blendMat:setVec2("u_pos", value)
        self.userPosition:set(value.x, value.y, 0)
    elseif name == "u_angle" then
        -- self.videoMat:setFloat("u_angle", value)
        -- self.blendMat:setFloat("u_angle", value)
        self.userEulerAngle:set(0, 0, value / math.pi * 180)
    elseif name == "u_scale" then
        -- self.videoMat:setFloat("u_scale", value)
        -- self.blendMat:setFloat("u_scale", value * self.scaleCorrect)
        self.userScale:set(value, value, 1)
    elseif name == "u_flipX" then
        self.videoMat:setFloat("u_flipX", value)
    elseif name == "u_flipY" then
        self.videoMat:setFloat("u_flipY", value)
    elseif name == "_alpha" then
        self.blendMat:setFloat("_alpha", value)
    end
end

function SeekModeScript:setDuration (duration)
    self.duration = duration
end

function SeekModeScript:_adapt_onStart (comp)
    self.curTime = 0
    self.duration = 2.0
    self.values = {}
    self.params = {}
    self.anims = {}
    self.animDirty = true
    self.entity = comp.entity
    self.scaleCorrect = 1.0
    self.videoMat = self.entity.scene:findEntityBy("video"):getComponent("MeshRenderer").material
    self.modelMat = self.entity.scene:findEntityBy("quad"):getComponent("MeshRenderer").material
    self.fxaaMat = self.entity.scene:findEntityBy("fxaa"):getComponent("MeshRenderer").material
    self.blendMat = self.entity.scene:findEntityBy("blend"):getComponent("MeshRenderer").material
    self.transform = self.entity.scene:findEntityBy("quad"):getComponent("Transform")
    self.userPosition = Amaz.Vector3f(0, 0, 0)
    self.userEulerAngle = Amaz.Vector3f(0, 0, 0)
    self.userScale = Amaz.Vector3f(1, 1, 1)
end

function SeekModeScript:_adapt_seek (time)
    local inputW = Amaz.BuiltinObject:getInputTextureWidth()
    local inputH = Amaz.BuiltinObject:getInputTextureHeight()
    local inputRatio = inputW / inputH
    local outputW = Amaz.BuiltinObject:getOutputTextureWidth()
    local outputH = Amaz.BuiltinObject:getOutputTextureHeight()
    local outputRatio = outputW / outputH
    local fitScale = Amaz.Vector3f(1, 1, 1)
    local extraScale = 1
    if inputRatio < outputRatio then
        fitScale.x = inputRatio
        extraScale = inputH / outputH
    else
        fitScale.x = outputRatio
        fitScale.y = outputRatio / inputRatio
        extraScale = inputW / outputW
    end

    local uvScale = Amaz.Vector2f(1, 1)
    local xRatio = inputRatio / outputRatio
    local yRatio = outputRatio / inputRatio
    if outputRatio > 1. then
        if outputRatio > inputRatio then
            uvScale.x = xRatio
        else
            uvScale.y = yRatio
        end
    elseif math.abs(outputRatio - 1.) < .1 then
        if inputRatio < 1. then
            uvScale.x = xRatio
        else
            uvScale.y = yRatio
        end
    elseif outputRatio < 1. then
        if math.abs(inputRatio - 1.) < .1 or outputRatio < inputRatio then
            uvScale.y = yRatio
        else
            uvScale.x = xRatio
        end
    end

    self.modelMat:setFloat("u_OutputWidth", outputW)
    self.modelMat:setFloat("u_OutputHeight", outputH)

    local userMat = Amaz.Matrix4x4f()
    userMat:setTRS(
        Amaz.Vector3f(self.userPosition.x * outputRatio, self.userPosition.y, self.userPosition.z),
        Amaz.Quaternionf.EulerToQuaternion(-self.userEulerAngle / 180 * math.pi),
        Amaz.Vector3f(1, 1, 1) * self.userScale.x * extraScale
    )
    userMat:invert_Full()

    local fitMat = Amaz.Matrix4x4f()
    fitMat:setTRS(Amaz.Vector3f(0, 0, 0), Amaz.Quaternionf.identity(), Amaz.Vector3f(uvScale.x, uvScale.y, 1))
    fitMat:invert_Full()

    self.modelMat:setMat4("userMat", userMat)
    self.modelMat:setMat4("fitMat", fitMat)
end


